"Showing {EL} {orbLabel} · n = {n}, l = {l}{orb} · drag the stage to turn it": "Mostrando {EL} {orbLabel} · n = {n}, l = {l}{orb} · arrastra el escenario para girarlo",
"The math, step 1 and step 9 · Predict, \"Common mistakes\" · NGSS HS-PS1-1": "Las matemáticas, paso 1 y paso 9 · Predecir, \"Errores comunes\" · NGSS HS-PS1-1",
