"<span id=\"emptyStat\">99.999 999 999 99 %</span> of the volume of <span data-el=\"atom\">an iron atom</span> is empty space.": "<span id=\"emptyStat\">99.999 999 999 99 %</span> del volumen de <span data-el=\"atom\">un átomo de hierro</span> es espacio vacío.",
"Hydrogen&rsquo;s nucleus is a single proton: no neutrons and no binding energy, nothing to hold together. Every heavier nucleus is held by the strong nuclear force, which reaches only about one nucleon&rsquo;s width.": "El núcleo del hidrógeno es un solo protón: sin neutrones y sin energía de enlace, nada que mantener unido. Todos los núcleos más pesados los sujeta la fuerza nuclear fuerte, que alcanza solo más o menos el ancho de un nucleón.",
"Now put the electron in two levels at once. The phases beat and the cloud starts to <b>slosh</b>, 2.47 × 10¹⁵ times a second, slowed here about 10¹⁵ times. A sloshing charge is an antenna: this motion is what sends out hydrogen&rsquo;s ultraviolet Lyman-α light.": "Ahora pon el electrón en dos niveles a la vez. Las fases baten y la nube empieza a <b>balancearse</b>, 2.47 × 10¹⁵ veces por segundo, frenada aquí unas 10¹⁵ veces. Una carga que se balancea es una antena: este movimiento es lo que emite la luz ultravioleta Lyman-α del hidrógeno.",
"This is {v} <b>{v2}</b> orbital, computed rather than drawn: <b>ψ = R(r) · Y(θ, φ)</b>. It holds the electron that puts {v3} in the {v4} block{v5}. The other {v6} electron{v7} screen the nucleus, so it feels a charge of about <b>{v8}</b>, not {v9} (Slater&rsquo;s rules).": "Este es el orbital <b>{v2}</b> {v}, calculado en vez de dibujado: <b>ψ = R(r) · Y(θ, φ)</b>. Contiene el electrón que pone el {v3} en el bloque {v4}{v5}. Los otros {v6} {v7, select, s {electrones apantallan} other {electrón apantalla}} el núcleo, así que siente una carga de cerca de <b>{v8}</b>, no {v9} (reglas de Slater).",
"Now every electron at once: <b>{v}</b> of them, in shells of {v2}. Each subshell is a hydrogen-like cloud with its own screened charge, and together they make the atom&rsquo;s layered glow. The brightness here is logarithmic: the innermost shell is thousands of times denser than the outermost.": "Ahora todos los electrones a la vez: <b>{v}</b> en total, en capas de {v2}. Cada subcapa es una nube hidrogenoide con su propia carga apantallada, y juntas forman el brillo en capas del átomo. El brillo aquí es logarítmico: la capa más interna es miles de veces más densa que la más externa.",
"<b>{v}</b> nucleons: <b>{v2}</b> proton{v3} that push each other apart and <b>{v4}</b> neutron{v5}, held together by the strong nuclear force, which reaches only about one nucleon&rsquo;s width. Building {v6}-{v7} releases <b>{v8} MeV</b>{v9}, so it weighs less than its loose parts by exactly that much: E = mc².": "<b>{v}</b> nucleones: <b>{v2}</b> {v3, select, s {protones que se repelen} other {protón}} y <b>{v4}</b> {v5, select, s {neutrones} other {neutrón}}, unidos por la fuerza nuclear fuerte, que alcanza solo más o menos el ancho de un nucleón. Construir {v6}-{v7} libera <b>{v8} MeV</b>{v9}, así que pesa exactamente eso menos que sus partes sueltas: E = mc².",
"Computed for Hα: 656.470 nm. Measured by the US National Institute of Standards and Technology (NIST): 656.463 nm. The seven picometers in between are physics the formula leaves out: relativity, the electron&rsquo;s spin, and quantum electrodynamics (QED). In 2026 hydrogen tested the Standard Model to better than a part per trillion.": "Calculado para Hα: 656.470 nm. Medido por el Instituto Nacional de Estándares y Tecnología de EE. UU. (NIST): 656.463 nm. Los siete picómetros de diferencia son física que la fórmula deja fuera: la relatividad, el espín del electrón y la electrodinámica cuántica (QED). En 2026 el hidrógeno puso a prueba el modelo estándar por debajo de una parte por billón.",
