"<span class=\"hint\">probe energy Q</span><input type=\"range\" id=\"asQ\" min=\"0\" max=\"1000\" step=\"1\" value=\"{v}\" style=\"flex:1 1 90px;min-width:90px\"><span class=\"hint\" id=\"asReadout\" style=\"font-family:var(--mono);color:var(--acc)\">Q={Qm} GeV · αs={asm}</span>": "<span class=\"hint\">energía de la sonda Q</span><input type=\"range\" id=\"asQ\" min=\"0\" max=\"1000\" step=\"1\" value=\"{v}\" style=\"flex:1 1 90px;min-width:90px\"><span class=\"hint\" id=\"asReadout\" style=\"font-family:var(--mono);color:var(--acc)\">Q={Qm} GeV · αs={asm}</span>",
