"<span><i style=\"background:var(--acc2)\"></i>quark energy</span><span><i style=\"background:var(--acc)\"></i>gluon field energy</span><span><i style=\"background:var(--warn)\"></i>trace anomaly</span><span><i style=\"background:var(--psiP)\"></i>quark-mass term</span>": "<span><i style=\"background:var(--acc2)\"></i>energía de los quarks</span><span><i style=\"background:var(--acc)\"></i>energía del campo de gluones</span><span><i style=\"background:var(--warn)\"></i>anomalía de la traza</span><span><i style=\"background:var(--psiP)\"></i>término de masa de los quarks</span>",
"<span><i style=\"background:var(--acc2)\"></i>valence u,u,d</span><span><i style=\"background:var(--warn)\"></i>sea qq̄ pairs</span><span><i style=\"background:var(--acc)\"></i>gluons</span><span style=\"color:var(--ink3)\">momentum fractions, Q²≈10 GeV²</span>": "<span><i style=\"background:var(--acc2)\"></i>de valencia u,u,d</span><span><i style=\"background:var(--warn)\"></i>pares qq̄ del mar</span><span><i style=\"background:var(--acc)\"></i>gluones</span><span style=\"color:var(--ink3)\">fracciones del momento, Q²≈10 GeV²</span>",
"<span><i style=\"background:var(--psiP)\"></i>quark rest mass (Higgs)</span><span><i style=\"background:var(--acc)\"></i>gluon field + confined motion (E=mc²)</span>": "<span><i style=\"background:var(--psiP)\"></i>masa en reposo de los quarks (Higgs)</span><span><i style=\"background:var(--acc)\"></i>campo de gluones + movimiento confinado (E=mc²)</span>",
"Can oxygen be pulled from lunar soil or Martian air at the tonnes-per-year scale that crews and return rockets would need?": "¿Se puede extraer oxígeno del suelo lunar o del aire marciano a la escala de toneladas por año que necesitarían las tripulaciones y los cohetes de regreso?",
"asymmetry: costs energy to have N &ne; Z &nbsp;= <b>{num}</b>": "asimetría: tener N &ne; Z cuesta energía &nbsp;= <b>{num}</b>",
"pairing: even numbers bind better &nbsp;= <b>{tP}{num}</b>": "apareamiento: los números pares se enlazan mejor &nbsp;= <b>{tP}{num}</b>",
"surface: nucleons on the skin bond to fewer &nbsp;= <b>{num}</b>": "superficie: los nucleones de la piel se enlazan con menos vecinos &nbsp;= <b>{num}</b>",
"volume: bulk glue, every nucleon bonds to its neighbors &nbsp;= <b>{num}</b>": "volumen: pegamento en bloque, cada nucleón se enlaza con sus vecinos &nbsp;= <b>{num}</b>",
"A living periodic table you learn by doing: build atoms from their particles, test yourself, calculate with real formulas, hear each element's light, and fall into any element down to the quarks. Free, open source, works offline.": "Una tabla periódica viva que aprendes haciendo: construye átomos a partir de sus partículas, ponte a prueba, calcula con fórmulas reales, escucha la luz de cada elemento y cae dentro de cualquier elemento hasta los quarks. Gratuita, de código abierto, funciona sin conexión.",
"Atom for teachers: assign any lab in one link": "Atom para docentes: asigna cualquier laboratorio con un enlace",
"Atom: a one-page handout for students, teachers, and families": "Atom: un folleto de una página para estudiantes, docentes y familias",
"Atom: every element, down to the quarks": "Atom: cada elemento, hasta los quarks",
"How to use Atom in a chemistry or physics class: a link for every lab, step, and element; worksheets with answer keys; turn-in codes; five lesson paths with exit checks; Spanish and reading supports; and a map to NGSS and AP Chemistry.": "Cómo usar Atom en una clase de química o física: un enlace para cada laboratorio, paso y elemento; hojas de trabajo con claves de respuestas; códigos de entrega; cinco rutas de lección con pruebas de salida; español y apoyos a la lectura; y un mapa a NGSS y AP Chemistry.",
"Not found: Atom": "No encontrada: Atom",
"One printable page about Atom, the free periodic table that computes every element: how to start, how it is assigned, how progress is collected, and what it keeps private. In English and Spanish.": "Una página imprimible sobre Atom, la tabla periódica gratuita que calcula cada elemento: cómo empezar, cómo se asigna, cómo se recoge el progreso y qué mantiene privado. En inglés y en español.",
"&int;<sub>0</sub><sup>1</sup> x [ &Sigma;<sub>q</sub>(q(x)+q&#772;(x)) + g(x) ] dx = 1": "&int;<sub>0</sub><sup>1</sup> x [ &Sigma;<sub>q</sub>(q(x)+q&#772;(x)) + g(x) ] dx = 1",
